//! Video and audio operations end to end, with the real FFmpeg and ffprobe. Fixtures are
//! generated by FFmpeg itself (test patterns and tones). Tests are skipped, with a message,
//! when FFmpeg is missing.

mod common;

use std::path::Path;
use std::process::Command;

use common::*;
use easy_converter_lib::error::ErrorCode;
use easy_converter_lib::tools::ffmpeg::{self, MediaInfo};
use easy_converter_lib::tools::ToolId;
use serde_json::json;

async fn env(name: &str) -> Option<Env> {
    let env = Env::new(name).with_tools().await;
    (env.has(ToolId::Ffmpeg) && env.has(ToolId::Ffprobe)).then_some(env)
}

/// Runs the system FFmpeg to create a fixture.
fn ffmpeg(args: &[&str], out: &Path) {
    let status = Command::new("ffmpeg")
        .args(["-hide_banner", "-loglevel", "error", "-y"])
        .args(args)
        .arg(out)
        .status()
        .expect("ffmpeg should run");
    assert!(status.success(), "could not create {}", out.display());
}

/// A test-pattern video with a tone, `secs` long, in the codecs the extension suggests.
fn video(out: &Path, size: &str, secs: u32, with_audio: bool) {
    let src = format!("testsrc=size={size}:rate=25:duration={secs}");
    let tone = format!("sine=frequency=440:sample_rate=48000:duration={secs}");
    let mut args = vec!["-f", "lavfi", "-i", &src];
    if with_audio {
        args.extend(["-f", "lavfi", "-i", &tone]);
    }
    let webm = out.extension().is_some_and(|e| e == "webm");
    if webm {
        args.extend([
            "-c:v",
            "libvpx-vp9",
            "-deadline",
            "realtime",
            "-cpu-used",
            "8",
        ]);
    } else {
        args.extend([
            "-c:v",
            "libx264",
            "-preset",
            "ultrafast",
            "-pix_fmt",
            "yuv420p",
        ]);
    }
    if with_audio {
        args.extend(["-c:a", if webm { "libopus" } else { "aac" }, "-ac", "2"]);
    }
    // Key frame every second, so fast cuts land near the asked time.
    args.extend(["-g", "25"]);
    ffmpeg(&args, out);
}

fn tone(out: &Path, secs: u32, volume: f32) {
    let src = format!("sine=frequency=440:sample_rate=44100:duration={secs}");
    let filter = format!("volume={volume}");
    ffmpeg(
        &["-f", "lavfi", "-i", &src, "-af", &filter, "-ac", "2"],
        out,
    );
}

async fn probe(env: &Env, path: &Path) -> MediaInfo {
    ffmpeg::probe(&env.tools, path)
        .await
        .expect("output should be readable")
}

fn assert_duration(info: &MediaInfo, ms: u64, tolerance: u64) {
    let got = info.duration_ms.expect("duration known");
    assert!(
        got.abs_diff(ms) <= tolerance,
        "duration {got} ms, expected about {ms} ms"
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn convert_copies_when_possible_and_encodes_otherwise() {
    let Some(env) = env("video-convert").await else {
        return;
    };
    let input = env.path("clip.mp4");
    video(&input, "320x240", 2, true);

    let mkv = assert_done(
        &env.run_json(json!({ "type": "videoConvert", "input": input, "container": "mkv" }))
            .await,
    );
    assert_eq!(mkv.extension().unwrap(), "mkv");
    let info = probe(&env, &mkv).await;
    assert_eq!(
        info.video.as_ref().unwrap().codec,
        "h264",
        "video should be copied"
    );
    assert_eq!(info.audio[0].codec, "aac", "audio should be copied");
    assert_duration(&info, 2000, 100);

    let webm = assert_done(
        &env.run_json(json!({ "type": "videoConvert", "input": input, "container": "webm" }))
            .await,
    );
    let info = probe(&env, &webm).await;
    assert!(["vp9", "vp8"].contains(&info.video.as_ref().unwrap().codec.as_str()));
    assert!(["opus", "vorbis"].contains(&info.audio[0].codec.as_str()));
}

fn fs_len(path: &Path) -> u64 {
    std::fs::metadata(path).unwrap().len()
}

#[tokio::test(flavor = "multi_thread")]
async fn trim_fast_and_accurate() {
    let Some(env) = env("video-trim").await else {
        return;
    };
    let input = env.path("clip.mp4");
    video(&input, "160x120", 4, true);

    let range = json!({ "startMs": 1000, "endMs": 3000 });
    for accurate in [false, true] {
        let out = assert_done(
            &env.run_json(json!({ "type": "videoTrim", "input": input, "range": range, "accurate": accurate }))
                .await,
        );
        assert_duration(&probe(&env, &out).await, 2000, 150);
    }
    // To the end of the file.
    let out = assert_done(
        &env.run_json(json!({ "type": "videoTrim", "input": input, "range": { "startMs": 3000 } }))
            .await,
    );
    assert_duration(&probe(&env, &out).await, 1000, 150);

    let past = env
        .run_json(json!({ "type": "videoTrim", "input": input, "range": { "startMs": 10000 } }))
        .await;
    assert_failed(&past, ErrorCode::InvalidParameter);
}

#[tokio::test(flavor = "multi_thread")]
async fn compress_and_resize() {
    let Some(env) = env("video-compress").await else {
        return;
    };
    let input = env.path("clip.mp4");
    video(&input, "320x240", 2, true);

    let out = assert_done(
        &env.run_json(json!({ "type": "videoCompress", "input": input, "quality": "low" }))
            .await,
    );
    assert!(
        fs_len(&out) <= fs_len(&input),
        "never bigger than the original"
    );
    assert_duration(&probe(&env, &out).await, 2000, 100);

    let out = assert_done(
        &env.run_json(json!({ "type": "videoResize", "input": input, "height": 120 }))
            .await,
    );
    let info = probe(&env, &out).await;
    let v = info.video.unwrap();
    assert_eq!((v.width, v.height), (160, 120));
    assert_eq!(info.audio[0].codec, "aac");
}

#[tokio::test(flavor = "multi_thread")]
async fn extract_audio_and_make_a_gif() {
    let Some(env) = env("video-audio-gif").await else {
        return;
    };
    let input = env.path("clip.mp4");
    video(&input, "320x240", 2, true);

    let original = assert_done(
        &env.run_json(json!({ "type": "videoExtractAudio", "input": input }))
            .await,
    );
    assert_eq!(original.extension().unwrap(), "m4a");
    let info = probe(&env, &original).await;
    assert!(info.video.is_none());
    assert_eq!(info.audio[0].codec, "aac");

    let mp3 = assert_done(
        &env.run_json(json!({ "type": "videoExtractAudio", "input": input, "format": "mp3" }))
            .await,
    );
    assert_eq!(probe(&env, &mp3).await.audio[0].codec, "mp3");

    let gif = assert_done(
        &env.run_json(json!({
            "type": "videoToGif", "input": input, "fps": 5, "width": 100,
            "range": { "startMs": 500, "endMs": 1500 }
        }))
        .await,
    );
    let info = probe(&env, &gif).await;
    let v = info.video.unwrap();
    assert_eq!((v.codec.as_str(), v.width), ("gif", 100));
    assert!(std::fs::read(&gif).unwrap().starts_with(b"GIF89a"));

    // A video without sound has no audio to extract.
    let silent = env.path("silent.mp4");
    video(&silent, "160x120", 1, false);
    let job = env
        .run_json(json!({ "type": "videoExtractAudio", "input": silent }))
        .await;
    assert_failed(&job, ErrorCode::InvalidFile);
}

#[tokio::test(flavor = "multi_thread")]
async fn merge_copies_matching_videos_and_re_encodes_mixed_ones() {
    let Some(env) = env("video-merge").await else {
        return;
    };
    // Names that look like options or break quoting must be handled.
    let a = env.path("-it's a.mp4");
    let b = env.path("b.mp4");
    video(&a, "320x240", 2, true);
    video(&b, "320x240", 1, true);

    let out = assert_done(
        &env.run_json(json!({ "type": "videoMerge", "inputs": [a, b] }))
            .await,
    );
    let info = probe(&env, &out).await;
    assert_duration(&info, 3000, 150);
    assert_eq!(info.video.unwrap().codec, "h264");

    // Different size, codec and no audio: joined with the first video's shape.
    let c = env.path("c.webm");
    video(&c, "160x160", 1, false);
    let out = assert_done(
        &env.run_json(json!({ "type": "videoMerge", "inputs": [a, c] }))
            .await,
    );
    let info = probe(&env, &out).await;
    assert_duration(&info, 3000, 200);
    let v = info.video.as_ref().unwrap();
    assert_eq!((v.width, v.height), (320, 240));
    assert_eq!(info.audio.len(), 1);
}

#[tokio::test(flavor = "multi_thread")]
async fn remove_and_replace_the_audio_track() {
    let Some(env) = env("video-track").await else {
        return;
    };
    let input = env.path("clip.mp4");
    video(&input, "160x120", 2, true);
    let music = env.path("music.wav");
    tone(&music, 5, 0.5);

    let out = assert_done(
        &env.run_json(
            json!({ "type": "videoAudioTrack", "input": input, "action": { "mode": "remove" } }),
        )
        .await,
    );
    let info = probe(&env, &out).await;
    assert!(info.audio.is_empty());
    assert_eq!(info.video.unwrap().codec, "h264");

    let out = assert_done(
        &env.run_json(json!({
            "type": "videoAudioTrack", "input": input, "action": { "mode": "replace", "audio": music }
        }))
        .await,
    );
    let info = probe(&env, &out).await;
    assert_eq!(info.audio[0].codec, "aac");
    assert_duration(&info, 2000, 150);
}

#[tokio::test(flavor = "multi_thread")]
async fn audio_convert_trim_normalize_and_mono() {
    let Some(env) = env("audio").await else {
        return;
    };
    let input = env.path("tone.wav");
    tone(&input, 3, 0.05);

    let mp3 = assert_done(
        &env.run_json(
            json!({ "type": "audioConvert", "input": input, "format": "mp3", "bitrateKbps": 128 }),
        )
        .await,
    );
    assert_eq!(probe(&env, &mp3).await.audio[0].codec, "mp3");
    let flac = assert_done(
        &env.run_json(json!({ "type": "audioConvert", "input": input, "format": "flac" }))
            .await,
    );
    assert_eq!(probe(&env, &flac).await.audio[0].codec, "flac");

    let cut = assert_done(
        &env.run_json(json!({ "type": "audioTrim", "input": mp3, "range": { "startMs": 500, "endMs": 2000 } })).await,
    );
    assert_eq!(cut.extension().unwrap(), "mp3");
    assert_duration(&probe(&env, &cut).await, 1500, 100);

    let loud = assert_done(
        &env.run_json(json!({ "type": "audioNormalize", "input": input }))
            .await,
    );
    let info = probe(&env, &loud).await;
    assert_eq!(info.audio[0].sample_rate, Some(44_100));
    assert!(
        peak_db(&loud) > peak_db(&input) + 6.0,
        "a quiet tone should get louder"
    );

    let mono = assert_done(
        &env.run_json(json!({ "type": "audioMono16k", "input": input }))
            .await,
    );
    let a = &probe(&env, &mono).await.audio[0];
    assert_eq!(
        (a.codec.as_str(), a.sample_rate, a.channels),
        ("pcm_s16le", Some(16_000), Some(1))
    );
}

/// Peak level of a file in dB, measured by FFmpeg's volumedetect.
fn peak_db(path: &Path) -> f64 {
    let out = Command::new("ffmpeg")
        .args(["-hide_banner", "-nostats", "-i"])
        .arg(path)
        .args(["-af", "volumedetect", "-f", "null", "-"])
        .output()
        .unwrap();
    let text = String::from_utf8_lossy(&out.stderr);
    text.lines()
        .find_map(|l| l.split("max_volume:").nth(1))
        .and_then(|v| v.trim().trim_end_matches("dB").trim().parse().ok())
        .expect("volumedetect output")
}

#[tokio::test(flavor = "multi_thread")]
async fn damaged_and_fake_files_fail_cleanly() {
    let Some(env) = env("media-bad").await else {
        return;
    };
    let fake = env.path("fake.mp4");
    std::fs::write(&fake, b"#EXTM3U\n#EXTINF:1,\nhttp://127.0.0.1:9/x.ts\n").unwrap();
    let job = env
        .run_json(json!({ "type": "videoConvert", "input": fake, "container": "mkv" }))
        .await;
    assert_failed(&job, ErrorCode::InvalidFile);

    let truncated = env.path("cut.mp4");
    video(&truncated, "160x120", 1, true);
    let bytes = std::fs::read(&truncated).unwrap();
    std::fs::write(&truncated, &bytes[..bytes.len() / 3]).unwrap();
    let job = env
        .run_json(json!({ "type": "audioMono16k", "input": truncated }))
        .await;
    assert_eq!(job.status, easy_converter_lib::jobs::JobStatus::Failed);
}

#[tokio::test(flavor = "multi_thread")]
async fn bad_requests_and_missing_tools_are_refused_before_queueing() {
    let env = Env::new("media-refused");
    let clip = env.path("clip.mp4");
    std::fs::write(&clip, b"x").unwrap();
    let build = |value: serde_json::Value| {
        easy_converter_lib::ops::build_job(
            serde_json::from_value(value).unwrap(),
            &env.ops_context(),
        )
        .err()
        .map(|e| e.code())
    };
    assert_eq!(
        build(json!({ "type": "videoConvert", "input": clip, "container": "mp4" })),
        Some(ErrorCode::ToolMissing)
    );

    let Some(env) = self::env("media-refused-tools").await else {
        return;
    };
    let clip = env.path("clip.mp4");
    std::fs::write(&clip, b"x").unwrap();
    let text = env.path("notes.txt");
    std::fs::write(&text, b"x").unwrap();
    let build = |value: serde_json::Value| {
        easy_converter_lib::ops::build_job(
            serde_json::from_value(value).unwrap(),
            &env.ops_context(),
        )
        .err()
        .map(|e| e.code())
    };
    for request in [
        json!({ "type": "videoConvert", "input": text, "container": "mp4" }),
        json!({ "type": "videoTrim", "input": clip, "range": { "startMs": 5000, "endMs": 1000 } }),
        json!({ "type": "videoResize", "input": clip, "height": 721 }),
        json!({ "type": "videoResize", "input": clip, "height": 10000 }),
        json!({ "type": "videoToGif", "input": clip, "fps": 60, "width": 320 }),
        json!({ "type": "videoToGif", "input": clip, "fps": 10, "width": 5000 }),
        json!({ "type": "videoMerge", "inputs": [clip] }),
        json!({ "type": "audioConvert", "input": clip, "format": "mp3" }),
        json!({ "type": "audioConvert", "input": text, "format": "mp3", "bitrateKbps": 1000 }),
    ] {
        assert_eq!(
            build(request.clone()),
            Some(ErrorCode::InvalidParameter),
            "{request}"
        );
    }
}
